package controlplane

const productServicesTemplates = `
{{define "services"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Services and tools · gog-marketing</title>{{template "style" .}}</head><body><header><strong>gog-marketing</strong><nav><a href="/">Home</a><a href="/assets/{{.Connection.ID}}">Manage assets</a><form class="inline" method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button>Sign out</button></form></nav></header><main><h1>Services and tools</h1><p>Enable only the Workspace or Marketing services this account needs. Resource-backed marketing services use specific asset grants after discovery; curated read-only tools use explicit service/tool grants, and other capabilities remain excluded until a safe per-tool selector exists.</p>{{if .Error}}<div class="error">{{.Error}}</div>{{end}}{{if .Message}}<div class="message">{{.Message}}</div>{{end}}<form method="post" action="/assets/{{.Connection.ID}}/services/save"><input type="hidden" name="csrf" value="{{.CSRF}}">{{range .Groups}}<section class="card"><h2>{{.Category}}</h2>{{range .Services}}<div class="service"><div class="service-head"><div><h3>{{.Name}}</h3><p class="muted">{{if .ResourceModel}}Resource-level access{{else}}Service/tool access{{end}}{{if .Enabled}} · Enabled{{end}}</p></div><div class="service-actions">{{if .Enabled}}<input type="checkbox" checked disabled aria-label="{{.Name}} enabled">{{else}}<label><input type="checkbox" name="new_service" value="{{.Service}}"> Enable service</label>{{end}}{{if .Tool}}{{if .ResourceModel}}{{else}}<label><input type="checkbox" name="tool" value="{{.Service}}/{{.Tool}}"{{if .ToolEnabled}} checked{{end}}> {{.ToolLabel}}</label>{{end}}{{end}}</div></div></div>{{end}}</section>{{end}}<div class="saving"><button class="primary" type="submit">Save service access</button></div></form></main></body></html>{{end}}
`
